// The page's background: spears flying level across a fixed canvas behind the
// glass panels. The sprites, a hoplite spear and one carrying a shield edge-on
// (the logo in flight), are generated by tools/LOGO.ares; this only moves
// them. `launch` throws one from a given point, which the page does on every
// Run; that one flies on a second canvas in front of the page, since it is
// gone within a second and should not be lost behind the glass.
//
// Depth sets everything at once: a far spear is shorter, slower and fainter,
// so the volley reads as layered. With `prefers-reduced-motion` a few are
// drawn once, still.

const MAX_FLYING = 12;

interface Spear {
  x: number;
  y: number;
  /// Pixels a second; negative flies left.
  v: number;
  depth: number;
  shield: boolean;
}

function sprite(src: string): HTMLImageElement {
  const img = new Image();
  img.src = src;
  return img;
}
const plain = sprite("spear.png");
const carrying = sprite("spear-shield.png");

/// A canvas covering the viewport and the spears drawn on it, far to near.
interface Sky {
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  flying: Spear[];
}

function sky(className: string): Sky {
  const canvas = document.createElement("canvas");
  canvas.className = className;
  canvas.setAttribute("aria-hidden", "true");
  document.body.append(canvas);
  return { canvas, ctx: canvas.getContext("2d") as CanvasRenderingContext2D, flying: [] };
}
const back = sky("spears");
const front = sky("spears front");

const still = matchMedia("(prefers-reduced-motion: reduce)").matches;
let width = 0;
let height = 0;

function resize(): void {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  width = innerWidth;
  height = innerHeight;
  for (const { canvas, ctx } of [back, front]) {
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  if (still) scatter();
}

const between = (lo: number, hi: number) => lo + Math.random() * (hi - lo);
const length = (depth: number) => 90 + 140 * depth;

/// Keeps a sky ordered far to near, so near spears are drawn over far ones.
function add(to: Sky, s: Spear): void {
  const at = to.flying.findIndex((t) => t.depth > s.depth);
  to.flying.splice(at < 0 ? to.flying.length : at, 0, s);
}

/// A spear entering from either side at a random height.
function throwOne(): Spear {
  const depth = between(0.3, 1);
  const right = Math.random() < 0.5;
  return {
    x: right ? 0 : width,
    y: between(20, height - 20),
    v: (120 + 260 * depth) * (right ? 1 : -1),
    depth,
    shield: Math.random() < 0.15,
  };
}

/// Throws a spear from (x, y) in page coordinates, fast and to the left,
/// across the page.
export function launch(x: number, y: number): void {
  if (still) return;
  add(front, { x, y, v: -1100, depth: 1, shield: false });
}

/// Draws a spear whose point is at (x, y) when it flies right. The sprite
/// points right, so a spear flying left is drawn mirrored about x.
function draw(ctx: CanvasRenderingContext2D, s: Spear): void {
  const img = s.shield ? carrying : plain;
  if (!img.complete || img.naturalWidth === 0) return;
  const len = length(s.depth);
  const tall = (len * img.naturalHeight) / img.naturalWidth;
  ctx.save();
  ctx.globalAlpha = 0.35 + 0.6 * s.depth;
  ctx.translate(s.x, s.y);
  if (s.v < 0) ctx.scale(-1, 1);
  ctx.drawImage(img, -len, -tall / 2, len, tall);
  ctx.restore();
}

/// For reduced motion: a few spears frozen mid-flight.
function scatter(): void {
  back.ctx.clearRect(0, 0, width, height);
  for (let i = 0; i < 9; i++) {
    const s = throwOne();
    s.x = between(0, width);
    draw(back.ctx, s);
  }
}

/// Moves a sky's spears on by `dt` seconds, drops those that have left the
/// screen, and redraws the rest.
function fly({ ctx, flying }: Sky, dt: number): void {
  ctx.clearRect(0, 0, width, height);
  for (let i = flying.length - 1; i >= 0; i--) {
    const s = flying[i];
    s.x += s.v * dt;
    const len = length(s.depth);
    if (s.x < -len || s.x > width + len) flying.splice(i, 1);
  }
  for (const s of flying) draw(ctx, s);
}

let last = 0;
let wait = 0;
function frame(now: number): void {
  const dt = Math.min((now - last) / 1000, 0.05);
  last = now;
  wait -= dt;
  if (wait <= 0 && back.flying.length < MAX_FLYING) {
    add(back, throwOne());
    wait = between(0.4, 1.4);
  }
  fly(back, dt);
  fly(front, dt);
  requestAnimationFrame(frame);
}

addEventListener("resize", resize);
resize();
if (still) {
  plain.onload = scatter;
  carrying.onload = scatter;
} else {
  requestAnimationFrame((now) => { last = now; requestAnimationFrame(frame); });
}
